examples.code:
-- What the code meant to send:
SELECT id, email, role FROM users
WHERE email = 'ada@roombook.example';

-- What it sent when someone typed  ' OR '1'='1  as the email:
SELECT id, email, role FROM users
WHERE email = '' OR '1'='1';

PREPARE find_user (text) AS
  SELECT id, email, role FROM users WHERE email = $1;

EXECUTE find_user('ada@roombook.example');

EXECUTE find_user(''' OR ''1''=''1');

